INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Benötigt DHCPv6 im Gegensatz zu SLAAC einen Server?', 2, '[{"text": "Ja", "correct": true, "because": "DHCPv6 ist serverbasiert"}, {"text": "Nein", "correct": false, "because": "SLAAC ist serverlos"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Schritte hat SLAAC im Vergleich zu DHCPv6?', 3, '[{"text": "2", "correct": true, "because": "Router Advertisement, Adressbildung"}, {"text": "4", "correct": false, "because": "DHCPv6 hat 4 Schritte"}, {"text": "1", "correct": false, "because": "Zu wenig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verfahren bietet mehr Kontrolle über Adresszuweisung?', 4, '[{"text": "DHCPv6", "correct": true, "because": "Zentrale Verwaltung"}, {"text": "SLAAC", "correct": false, "because": "Autonom durch Clients"}, {"text": "Beides gleich", "correct": false, "because": "Unterschiedliche Ansätze"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SLAAC nutzt Router Advertisement. b) DHCPv6 ist schneller als SLAAC.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, Geschwindigkeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei SLAAC im Vergleich zu DHCPv6?', 5, '[{"text": "Serververwaltung", "correct": true, "because": "SLAAC ist serverlos"}, {"text": "Adressgenerierung", "correct": false, "because": "Kern beider Verfahren"}, {"text": "Router", "correct": false, "because": "SLAAC benötigt RA"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DHCPv6 DNS-Informationen liefern kann, im Gegensatz zu SLAAC?', 2, '[{"text": "Ja", "correct": true, "because": "DHCPv6 bietet Zusatzdaten"}, {"text": "Nein", "correct": false, "because": "SLAAC nur Adressen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verfahren ist für kleine Netze einfacher?', 3, '[{"text": "SLAAC", "correct": true, "because": "Keine Serverkonfiguration nötig"}, {"text": "DHCPv6", "correct": false, "because": "Server erforderlich"}, {"text": "Beides gleich", "correct": false, "because": "Unterschiedliche Komplexität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unterschiede gibt es zwischen DHCPv6 und SLAAC?', 5, '[{"text": "DHCPv6 ist serverbasiert", "correct": true, "because": "Benötigt DHCP-Server"}, {"text": "SLAAC nutzt Router", "correct": true, "because": "RA für Adressbildung"}, {"text": "SLAAC ist zentral gesteuert", "correct": false, "because": "Autonom"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DHCPv6 bietet mehr Konfiguration. b) SLAAC ist komplexer. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, SLAAC ist simpler"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für SLAAC, im Vergleich zu DHCPv6?', 4, '[{"text": "DHCP-Server", "correct": true, "because": "SLAAC ist serverlos"}, {"text": "Router Advertisement", "correct": false, "because": "SLAAC benötigt RA"}, {"text": "Client", "correct": false, "because": "Beide brauchen Clients"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DHCPv6 für große Netze besser als SLAAC?', 2, '[{"text": "Ja", "correct": true, "because": "Bessere Kontrolle"}, {"text": "Nein", "correct": false, "because": "SLAAC auch skalierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Szenarien passen zu DHCPv6 und SLAAC?', 4, '[{"text": "DHCPv6: Unternehmensnetze", "correct": true, "because": "Zentrale Verwaltung"}, {"text": "SLAAC: Heimnetze", "correct": true, "because": "Einfache Einrichtung"}, {"text": "SLAAC: Serverfarmen", "correct": false, "because": "Weniger Kontrolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass SLAAC keine DNS-Optionen bietet. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "Nur Adressbildung"}, {"text": "Nein", "correct": false, "because": "DHCPv6 bietet DNS"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei DHCPv6 gegenüber SLAAC?', 3, '[{"text": "Kontrolle", "correct": true, "because": "Zentrale Zuweisung"}, {"text": "Einfachheit", "correct": false, "because": "SLAAC ist simpler"}, {"text": "Geschwindigkeit", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SLAAC benötigt /64. b) DHCPv6 ist serverlos.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, DHCPv6 braucht Server"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten DHCPv6 und SLAAC?', 5, '[{"text": "DHCPv6: Zusatzoptionen", "correct": true, "because": "z. B. DNS"}, {"text": "SLAAC: Einfachheit", "correct": true, "because": "Keine Server nötig"}, {"text": "SLAAC: Zentrale Steuerung", "correct": false, "because": "Autonom"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei SLAAC im Vergleich zu DHCPv6 unwichtig?', 3, '[{"text": "Router", "correct": false, "because": "SLAAC benötigt RA"}, {"text": "Server", "correct": true, "because": "SLAAC ist serverlos"}, {"text": "Adressbildung", "correct": false, "because": "Kern beider"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist SLAAC schneller als DHCPv6?', 2, '[{"text": "Ja", "correct": true, "because": "Weniger Schritte"}, {"text": "Nein", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DHCPv6 für dynamische Netze besser ist?', 3, '[{"text": "Ja", "correct": true, "because": "Flexiblere Verwaltung"}, {"text": "Nein", "correct": false, "because": "SLAAC auch dynamisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verfahren wähle ich für ein Netz ohne Server?', 4, '[{"text": "SLAAC", "correct": true, "because": "Serverlos möglich"}, {"text": "DHCPv6", "correct": false, "because": "Server erforderlich"}, {"text": "Beides", "correct": false, "because": "Nur SLAAC passt"}]');
